<?php
namespace App\Console\Commands;use App\Models\AttendanceEvent;use App\Services\AttendanceEventService;use Illuminate\Console\Command;class CloseExpiredAttendanceEvents extends Command{protected $signature='sgsst:close-expired-attendance';protected $description='Cierra eventos de asistencia cuya ventana terminó';public function handle(AttendanceEventService $service):int{$count=0;AttendanceEvent::where('status','open')->where('attendance_closes_at','<=',now())->chunkById(100,function($events)use(&$count,$service){foreach($events as $event){$event->update(['status'=>'closed']);$service->audit($event,'attendance_event_closed',null,['automatic'=>true]);$count++;}});$this->info("Eventos cerrados: {$count}");return self::SUCCESS;}}
